values.value:
[
  [
    {
      "fieldName": "ucinn_ascendv2__Organizations_Related_Objects_To_Delete__c",
      "toolTip": "Object field api names that are related to accounts separated by commas.",
      "jsonFieldParams": {
        "type": "listNotJSON",
        "listNotJSONSeperator": ",",
        "listType": "value",
        "label": "Organizations Related Objects To Delete",
        "helpText": "Object field api names that are related to accounts that we want to delete when accounts are deleted.",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Account_Full_Name_Processing_Method__c",
      "toolTip": "When inserting or updating an existing name to type \"Full Name\", this setting controls whether we delete the other records, or change the other records to \"Former\".",
      "customFieldParams": {
        "type": "picklist",
        "label": "Organization Full Name Processing Method",
        "customPicklistValues": [
          {
            "label": "--None--",
            "value": ""
          },
          {
            "label": "Change",
            "value": "Change"
          },
          {
            "label": "Validate",
            "value": "Validate"
          },
          {
            "label": "Delete",
            "value": "Delete"
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Delete_Organization_With_Opportunities__c",
      "toolTip": "Check to allow deletion of organizations who have opportunities, uncheck to not allow deletion of organizations who have opportunities",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Allow deletion of Orgs with Oppties"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Do_Not_Delete_HH_on_Contact_Merge_Delete__c",
      "toolTip": "Do not delete household when we delete last contact in household, or when we merge two households, and the household has one contact left.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Do Not Delete HH on Contact Merge/Delete"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Household_Naming_Convention__c",
      "toolTip": "The naming convention rule for the household name.",
      "customFieldParams": {
        "type": "text",
        "label": "Household Naming Convention"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Household_to_Member_Mapping_v1__c",
      "toolTip": "A mapping listing the fields on the Household record to sync onto the related Household Member records.",
      "jsonFieldParams": {
        "type": "object",
        "label": "Household to Member Mapping",
        "keyLabel": "Household Field Api",
        "valueLabel": "Constituent Field Api",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Household_Name_Connector__c",
      "toolTip": "Joins multiple constituents together in the household name.",
      "customFieldParams": {
        "type": "text",
        "label": "Household Name Connector"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Member_to_Household_Mapping_v1__c",
      "toolTip": "A mapping listing the fields on the Primary Constituent to sync onto the corresponding Household record.",
      "jsonFieldParams": {
        "type": "object",
        "label": "Member to Household Mapping",
        "keyLabel": "Constituent Field Api",
        "valueLabel": "Household Field Api",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Household_Name_Overrun__c",
      "toolTip": "Text value that replaces a long list of names in a Household Name.",
      "customFieldParams": {
        "type": "text",
        "label": "Household Name Overrun"
      }
    },
    {
      "fieldName": "BLANK_HOUSEHOLD_NAME_OVERRUN"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Household_Name_Overrun_Count__c",
      "toolTip": "Number that indicates the maximum number of names to show. After this number, the Household Name Overrun text will be substituted for the remaining names.",
      "customFieldParams": {
        "type": "number",
        "label": "Household Name Overrun Count"
      }
    },
    {
      "fieldName": "BLANK_HOUSEHOLD_NAME_OVERRUN_COUNT"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Household_Automatic_Renaming__c",
      "toolTip": "Automatically rename the household name if the field(s) of any of the household member(s) specified in the Household Naming Convention changes, or if the household's members changes.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Enable Automatic Household Renaming"
      }
    }
  ]
]
